create table if not exists devices(id bigint generated by default as identity primary key,name text not null,status text not null default 'OFFLINE',last_seen timestamptz,created_at timestamptz default now());create table if not exists water_readings(id bigint generated by default as identity primary key,device_id bigint references devices(id),water_level_percentage numeric(5,2) not null,distance_cm numeric(8,2),pump_status boolean default false,buzzer_status boolean default false,created_at timestamptz default now());create table if not exists pump_events(id bigint generated by default as identity primary key,device_id bigint references devices(id),status boolean not null,trigger_type text not null,created_at timestamptz default now());create table if not exists alerts(id bigint generated by default as identity primary key,device_id bigint references devices(id),type text not null,message text not null,severity text not null,is_resolved boolean default false,created_at timestamptz default now());create table if not exists system_settings(id bigint generated by default as identity primary key,low_threshold numeric(5,2) default 30,high_threshold numeric(5,2) default 80,pump_mode text default 'AUTOMATIC',buzzer_enabled boolean default true,updated_at timestamptz default now());